440986.content:
@@preprocessing
<%
/* ===== 修炼控制器 =====
 * 只加载境界知识（能力/修炼/突破世界观设定）
 * 回复提示词由变量规则总控制器加载
 */

if (typeof curRealmFull === 'undefined') var curRealmFull = getvar('stat_data.当前境界', { defaults: '' });
if (typeof curState === 'undefined') var curState = getvar('stat_data._修炼状态', { defaults: '' });
if (typeof curProgress === 'undefined') var curProgress = getvar('stat_data.$修炼进度', { defaults: 0 });

// 从完整境界字符串提取大境界（如 "金丹期前期" → "金丹期"）
var curRealm = '';
var realms = ['炼气期', '筑基期', '金丹期', '元婴期', '化神期', '炼虚期', '合体期', '大乘期', '渡劫期', '真仙境'];
for (var i = 0; i < realms.length; i++) {
  if (curRealmFull.indexOf(realms[i]) === 0) {
    curRealm = realms[i];
    break;
  }
}

// 显示修炼进度信息
if (curState === '引气入体') {
  // 凡人引气入体
  print('\n【凡人】引气入体中\n');
} else if (curRealm && (curState === '修炼中' || curState === '突破中' || curState === '渡劫中' || curState === '')) {
  var realmInfo = '【' + curRealmFull + '】';
  if (curState === '修炼中') {
    realmInfo += '修炼中，进度：' + curProgress + '/100';
  } else if (curState === '突破中') {
    realmInfo += '突破中';
  } else if (curState === '渡劫中') {
    realmInfo += '渡劫中';
  } else {
    realmInfo += '当前进度：' + curProgress + '/100';
  }
  print('\n' + realmInfo + '\n');
}

// 按境界加载对应世界观知识
if (curRealm) {
  print(await getwi(curRealm + '能力'));
  if (curState === '修炼中') { print(await getwi(curRealm + '修炼')); }
  if (curState === '突破中') { print(await getwi(curRealm + '突破')); }
  // 渡劫中：加载当前大境界的突破知识（如金丹期大圆满渡劫中→加载金丹期突破）
  if (curState === '渡劫中') { print(await getwi(curRealm + '突破')); }
}
// 引气入体状态：凡人没有对应的境界修炼知识，不加载任何境界条目
%>

487026.content:
@@preprocessing
<%
/* ===== 变量规则总控制器 =====
 * 三层加载：知识(由其他控制器) + 变量规则 + 回复提示词
 * 根据前端写入的 _ 前缀状态变量，精准加载对应模块
 *
 * 注意：getwi() 必须加 await，否则条目内容不会被加载！
 */

// ═══ 修炼系统 ═══
if (typeof curState === 'undefined') var curState = getvar('stat_data._修炼状态', { defaults: '' });
if (curState !== '') {
  // 加载变量规则
  print(await getwi('[mvu_update]修炼变量更新规则'));
  // 加载对应的回复提示词
  if (curState === '修炼中') {
    print(await getwi('修炼中_回复提示词'));
  }
  if (curState === '突破中') {
    print(await getwi('突破中_回复提示词'));
  }
  if (curState === '渡劫中') {
    print(await getwi('渡劫中_回复提示词'));
  }
  if (curState === '引气入体') {
    print(await getwi('引气入体_回复提示词'));
  }
}

// ═══ 修真百艺 ═══
if (typeof curArt === 'undefined') var curArt = getvar('stat_data._当前百艺', { defaults: '' });
if (curArt !== '') {
  // 加载变量规则 + 回复提示词（百艺知识由百艺知识控制器加载）
  if (curArt === '炼丹') {
    print(await getwi('[mvu_update]修真百艺_炼丹变量更新规则'));
    print(await getwi('[mvu_update]修真百艺_丹道境界更新规则'));
    print(await getwi('炼丹_回复提示词'));
  }
  if (curArt === '炼器') {
    print(await getwi('[mvu_update]修真百艺_炼器变量更新规则'));
    print(await getwi('炼器_回复提示词'));
  }
  if (curArt === '阵法') {
    print(await getwi('[mvu_update]修真百艺_阵法变量更新规则'));
    print(await getwi('阵法_回复提示词'));
  }
  if (curArt === '符箓') {
    print(await getwi('[mvu_update]修真百艺_符箓变量更新规则'));
    print(await getwi('符箓_回复提示词'));
  }
  if (curArt === '驭兽') {
    print(await getwi('[mvu_update]修真百艺_驭兽变量更新规则'));
    print(await getwi('驭兽_回复提示词'));
  }
  if (curArt === '医术') {
    print(await getwi('[mvu_update]修真百艺_医术变量更新规则'));
    print(await getwi('医术_回复提示词'));
  }
  if (curArt === '傀儡术') {
    print(await getwi('[mvu_update]修真百艺_傀儡术变量更新规则'));
    print(await getwi('傀儡术_回复提示词'));
  }
  if (curArt === '种植采药') {
    print(await getwi('[mvu_update]修真百艺_种植采药变量更新规则'));
    print(await getwi('种植采药_回复提示词'));
  }
  // ═══ 钓鱼（统一纳入百艺体系，回复提示词由钓鱼EJS控制器加载） ═══
  if (curArt === '钓鱼') {
    print(await getwi('[mvu_update]钓鱼变量更新规则'));
  }
}
%>

