607312.content:
@@preprocessing
<%
/* ===== 用户输入扫描控制器 =====
 * 蓝灯常驻，@@preprocessing 确保在所有区域控制器之前执行
 * 扫描最后2条消息(含用户和AI)，匹配角色名/地名/势力名
 * 匹配到后加载：角色条目 + 所属宗门/势力全部条目
 * 结果记录到 _scanActivated 数组，供区域控制器判断是否跳过
 *
 * 互斥规则：扫描优先 → 区域控制器跳过已被扫描激活的条目
 */

// ═══ 初始化已激活列表 ═══
if (typeof _scanActivated === 'undefined') var _scanActivated = [];
var _scanText = '';

// ═══ 2. 直接获取变量（精简版） ═══
if (typeof lastUserMessage !== 'undefined' && lastUserMessage) _scanText += lastUserMessage + ' ';
if (typeof lastCharMessage !== 'undefined' && lastCharMessage) _scanText += lastCharMessage + ' ';

// 🚩 调试打印：确认精简后是否能拿到文本
console.log("【脚本调试】当前扫描文本：[" + _scanText + "]");

// ═══ 辅助函数：模糊匹配(支持简称) ═══
function _scanMatch(text, keywords) {
  for (var i = 0; i < keywords.length; i++) {
    if (text.indexOf(keywords[i]) !== -1) return true;
  }
  return false;
}

// ═══ 辅助函数：批量激活条目并记录 ═══
function _scanActivate(entries) {
  for (var i = 0; i < entries.length; i++) {
    if (_scanActivated.indexOf(entries[i]) === -1) {
      _scanActivated.push(entries[i]);
    }
  }
}

if (_scanText) {

// ═══════════════════════════════════════════════
// ███ 中央神州 ███
// ═══════════════════════════════════════════════

// --- 万剑山脉·剑宗 ---
if (_scanMatch(_scanText, ['剑宗'])) { _scanActivate(['剑宗']); }
if (_scanMatch(_scanText, ['殷冬雪'])) { _scanActivate(['剑宗', '殷冬雪']); }
if (_scanMatch(_scanText, ['卫疏影'])) { _scanActivate(['剑宗', '卫疏影']); }
if (_scanMatch(_scanText, ['姜千青'])) { _scanActivate(['剑宗', '姜千青']); }
if (_scanMatch(_scanText, ['叶霜寒'])) { _scanActivate(['剑宗', '叶霜寒']); }
if (_scanMatch(_scanText, ['谢云流'])) { _scanActivate(['剑宗', '谢云流']); }

// --- 洛红尘 ---
if (_scanMatch(_scanText, ['洛红尘', '红尘酒家'])) { _scanActivate(['洛红尘']); }

// --- 丹霞灵原·丹宗 ---
if (_scanMatch(_scanText, ['丹宗'])) { _scanActivate(['丹宗']); }
if (_scanMatch(_scanText, ['云蕴'])) { _scanActivate(['丹宗', '云蕴']); }
if (_scanMatch(_scanText, ['凌菲'])) { _scanActivate(['丹宗', '凌菲']); }

// --- 丹霞灵原·百草庐 ---
if (_scanMatch(_scanText, ['百草庐'])) { _scanActivate(['百草庐']); }
if (_scanMatch(_scanText, ['苏沐青'])) { _scanActivate(['百草庐', '苏沐青']); }
if (_scanMatch(_scanText, ['叶清'])) { _scanActivate(['百草庐', '叶清']); }
if (_scanMatch(_scanText, ['萧千翎'])) { _scanActivate(['百草庐', '萧千翎']); }
if (_scanMatch(_scanText, ['姜小满'])) { _scanActivate(['百草庐', '姜小满']); }
if (_scanMatch(_scanText, ['采薇'])) { _scanActivate(['采薇']); }

