@@preprocessing
<%
/* ===== 修炼控制器 =====
 * 只加载境界知识（能力/修炼/突破世界观设定）
 * 回复提示词由变量规则总控制器加载
 */

if (typeof curRealmFull === 'undefined') var curRealmFull = getvar('stat_data.当前境界', { defaults: '' });
if (typeof curState === 'undefined') var curState = getvar('stat_data._修炼状态', { defaults: '' });
if (typeof curProgress === 'undefined') var curProgress = getvar('stat_data.$修炼进度', { defaults: 0 });

// 从完整境界字符串提取大境界（如 "金丹期前期" → "金丹期"）
var curRealm = '';
var realms = ['炼气期', '筑基期', '金丹期', '元婴期', '化神期', '炼虚期', '合体期', '大乘期', '渡劫期', '真仙境'];
for (var i = 0; i < realms.length; i++) {
  if (curRealmFull.indexOf(realms[i]) === 0) {
    curRealm = realms[i];
    break;
  }
}

// 显示修炼进度信息
if (curState === '引气入体') {
  // 凡人引气入体
  print('\n【凡人】引气入体中\n');
} else if (curRealm && (curState === '修炼中' || curState === '突破中' || curState === '渡劫中' || curState === '')) {
  var realmInfo = '【' + curRealmFull + '】';
  if (curState === '修炼中') {
    realmInfo += '修炼中，进度：' + curProgress + '/100';
  } else if (curState === '突破中') {
    realmInfo += '突破中';
  } else if (curState === '渡劫中') {
    realmInfo += '渡劫中';
  } else {
    realmInfo += '当前进度：' + curProgress + '/100';
  }
  print('\n' + realmInfo + '\n');
}

// 按境界加载对应世界观知识
if (curRealm) {
  print(await getwi(curRealm + '能力'));
  if (curState === '修炼中') { print(await getwi(curRealm + '修炼')); }
  if (curState === '突破中') { print(await getwi(curRealm + '突破')); }
  // 渡劫中：加载当前大境界的突破知识（如金丹期大圆满渡劫中→加载金丹期突破）
  if (curState === '渡劫中') { print(await getwi(curRealm + '突破')); }
}
// 引气入体状态：凡人没有对应的境界修炼知识，不加载任何境界条目
%>

@@preprocessing
<%
/* ===== 变量规则总控制器 =====
 * 三层加载：知识(由其他控制器) + 变量规则 + 回复提示词
 * 根据前端写入的 _ 前缀状态变量，精准加载对应模块
 *
 * 注意：getwi() 必须加 await，否则条目内容不会被加载！
 */

// ═══ 修炼系统 ═══
if (typeof curState === 'undefined') var curState = getvar('stat_data._修炼状态', { defaults: '' });
if (curState !== '') {
  // 加载变量规则
